describe('Freeze First Column on Horizontal Scroll', () => {
  beforeEach(() => {
    cy.visit('/table-list');
  });

  it('should freeze the first column when scrolling horizontally', () => {
    // Verify table is visible and has multiple columns
    cy.get('[data-testid="table-container"]').should('be.visible');
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 1);
    cy.get('[data-testid="table-column"]').should('have.length.greaterThan', 1);

    // Scroll horizontally to trigger freeze
    cy.get('[data-testid="table-container"]').scrollLeft(1000);

    // Verify first column is frozen (should not scroll)
    cy.get('[data-testid="table-column-1"]').should('have.css', 'position', 'sticky');
    cy.get('[data-testid="table-column-1"]').should('have.css', 'left', '0px');

    // Verify other columns are scrollable
    cy.get('[data-testid="table-column-2"]').should('have.css', 'left', '100px');
    cy.get('[data-testid="table-column-3"]').should('have.css', 'left', '200px');

    // Scroll back to the left to verify first column remains frozen
    cy.get('[data-testid="table-container"]').scrollLeft(-1000);
    cy.get('[data-testid="table-column-1"]').should('have.css', 'left', '0px');

    // Verify table rows are still visible and scrollable
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 1);
    cy.get('[data-testid="table-row"]').first().should('be.visible');
  });

  it('should handle freeze when table is empty', () => {
    // Verify table is empty
    cy.get('[data-testid="table-container"]').should('be.visible');
    cy.get('[data-testid="table-row"]').should('have.length', 0);

    // Scroll horizontally to trigger freeze
    cy.get('[data-testid="table-container"]').scrollLeft(1000);

    // Verify first column is still frozen
    cy.get('[data-testid="table-column-1"]').should('have.css', 'position', 'sticky');
    cy.get('[data-testid="table-column-1"]').should('have.css', 'left', '0px');

    // Verify no rows are visible
    cy.get('[data-testid="table-row"]').should('not.exist');
  });
});
